package com.example.vozni_park.dto;

/**
 * Summary of what was generated by DataGenerationService.generateBenchmarkData().
 * Returned as the HTTP response body from POST /api/benchmark/generate.
 */
public record DataGenerationResult(
        int locationsGenerated,
        int vehiclesGenerated,
        int driversGenerated,
        int travelOrdersGenerated,
        int snapshotsGenerated,
        long elapsedMillis,
        boolean alreadyExists
) {
    /**
     * Returned when benchmark data is already present — generation was skipped.
     */
    public static DataGenerationResult alreadyExists(long existingOrderCount) {
        return new DataGenerationResult(0, 0, 0, (int) existingOrderCount, 0, 0, true);
    }
}